import { createAsyncThunk } from "@reduxjs/toolkit";
import { supabase } from "../../../../host/db.js";
import { editMessage } from "./edit-message.thunk.js";
import { mergeEditedText } from "./content-blocks.util.js";
import { markCacheBypass } from "./cache-bypass.slice.js";
import { invalidateConversationCache } from "./invalidate-conversation-cache.thunk.js";
import { executeInstance } from "../thunks/execute-instance.thunk.js";
import { loadConversation } from "../thunks/load-conversation.thunk.js";
const overwriteAndResend = createAsyncThunk(
  "messages/overwriteAndResend",
  async ({ conversationId, messageId, newContent }, { dispatch, getState, rejectWithValue }) => {
    const state = getState();
    const messagesEntry = state.messages.byConversationId[conversationId];
    const userMessage = messagesEntry?.byId?.[messageId];
    if (!userMessage) {
      return rejectWithValue({
        // access-errors: ok — browser-local Redux lookup; the message is absent from the loaded conversation slice, no record read involved
        message: `Message ${messageId} not found in conversation ${conversationId}`
      });
    }
    if (userMessage.role !== "user") {
      return rejectWithValue({
        message: "overwriteAndResend can only target user messages"
      });
    }
    const anchorPosition = userMessage.position;
    const downstreamIds = Object.values(messagesEntry?.byId ?? {}).filter((m) => m.position > anchorPosition && !m.deletedAt).map((m) => m.id);
    try {
      await dispatch(
        editMessage({
          conversationId,
          messageId,
          newContent: mergeEditedText(userMessage.content, newContent)
        })
      ).unwrap();
    } catch (err) {
      return rejectWithValue({
        message: err instanceof Error ? err.message : "Failed to write the edited message"
      });
    }
    const { error: truncErr } = await supabase.rpc(
      "cx_truncate_conversation_after",
      {
        p_conversation_id: conversationId,
        p_after_position: anchorPosition
      }
    );
    if (truncErr) {
      console.error(
        "[overwriteAndResend] cx_truncate_conversation_after failed:",
        truncErr
      );
      return rejectWithValue({
        message: truncErr.message ?? "Failed to truncate conversation after the edited message"
      });
    }
    const truncatedIds = downstreamIds;
    dispatch(markCacheBypass({ conversationId, conversation: true }));
    void dispatch(invalidateConversationCache({ conversationId }));
    try {
      await dispatch(loadConversation({ conversationId })).unwrap();
    } catch (err) {
      console.error(
        "[overwriteAndResend] loadConversation after truncate failed",
        err
      );
    }
    void dispatch(executeInstance({ conversationId, retry: true }));
    return { conversationId, truncatedMessageIds: truncatedIds };
  }
);
export {
  overwriteAndResend
};
